do $$
declare
  v_total integer; v_access integer; v_membership integer; v_review integer; v_dupes integer;
begin
  select count(*) into v_total from public.mtc_member_migration;
  select count(*) into v_access from public.mtc_member_migration where migration_status='READY – ACCESS';
  select count(*) into v_membership from public.mtc_member_migration where migration_status='READY – MEMBERSHIP';
  select count(*) into v_review from public.mtc_member_migration where migration_status='MANUAL REVIEW';
  select count(*) into v_dupes from (
    select lower(trim(email)), lower(trim(member_name)), lower(trim(teamup_membership)), lower(trim(membership_type))
    from public.mtc_member_migration
    group by 1,2,3,4 having count(*) > 1
  ) d;

  if v_total <> 302 then raise exception 'Expected 302 rows, got %', v_total; end if;
  if v_access <> 119 or v_membership <> 16 or v_review <> 167 then
    raise exception 'Unexpected status counts: ACCESS %, MEMBERSHIP %, REVIEW %', v_access, v_membership, v_review;
  end if;
  if v_dupes <> 0 then raise exception 'Duplicate groups detected: %', v_dupes; end if;
end $$;

commit;

select migration_status, count(*) as records
from public.mtc_member_migration
group by migration_status
order by migration_status;

select count(*) as total_records, count(distinct lower(email)) as unique_emails
from public.mtc_member_migration;
